    max_trade = max(tradeoff_scores) if tradeoff_scores else 1
    for i in range(len(archive)):
        norm_uniq = uniqueness_scores[i] / max_uniq if max_uniq > 0 else 0
        norm_trade = tradeoff_scores[i] / max_trade if max_trade > 0 else 0
        combined_scores.append(0.6 * norm_uniq + 0.4 * norm_trade)

