def select_neighbor(archive: List[Tuple[np.ndarray, Tuple[float, float]]], weight_lst: np.ndarray, value1_lst: np.ndarray, value2_lst: np.ndarray, capacity: float) -> np.ndarray:
    """
    Select a promising solution from the archive and generate a neighbor solution from it.

    Args:
    archive: List of (solution, objective) pairs. Each solution is a binary numpy array (0/1) of item selections.
             Each objective is a tuple of two float values (total value1, total value2).
    weight_lst: Numpy array of shape (N, ), item weights.
    value1_lst: Numpy array of shape (N, ), item values for objective 1.
    value2_lst: Numpy array of shape (N, ), item values for objective 2.
    capacity: Maximum allowed total weight.

    Returns:
    A new neighbor solution (numpy array).
    """
    if not archive:
        raise ValueError("Archive is empty")

    # Calculate marginal gains for each solution
    marginal_gains = []
    for sol, obj in archive:
        total_weight = np.sum(weight_lst * sol)
        if total_weight > capacity:
            marginal_gains.append((0, 0))
            continue
        # Calculate potential marginal gains if each item is flipped
        gains1 = []
        gains2 = []
        for i in range(len(sol)):
            if sol[i] == 1:
                new_weight = total_weight - weight_lst[i]
                if new_weight <= capacity:
                    gains1.append(value1_lst[i])
                    gains2.append(value2_lst[i])
            else:
                new_weight = total_weight + weight_lst[i]
                if new_weight <= capacity:
                    gains1.append(value1_lst[i])
                    gains2.append(value2_lst[i])
        marginal_gains.append((np.sum(gains1), np.sum(gains2)))

    # Calculate dominance ranks
    dominance_ranks = []
    for i, (obj_i, _) in enumerate(archive):
        rank = 0
        for j, (obj_j, _) in enumerate(archive):
            if i != j and (obj_j[0] >= obj_i[0] and obj_j[1] >= obj_i[1]) and (obj_j[0] > obj_i[0] or obj_j[1] > obj_i[1]):
                rank += 1
        dominance_ranks.append(rank)

    # Combine marginal gains and dominance ranks for selection
    scores = []
    for i, (gain1, gain2) in enumerate(marginal_gains):
        score = 0.6 * gain1 + 0.4 * gain2 - 0.2 * dominance_ranks[i]
        scores.append(score)

    selected_idx = np.argmax(scores)
    base_solution = archive[selected_idx][0].copy()
    new_solution = base_solution.copy()

    # Hybrid local search operator
    current_weight = np.sum(weight_lst * new_solution)
    impact_scores = (value1_lst + value2_lst) / (weight_lst + 1e-6)
    normalized_scores = impact_scores / (np.max(impact_scores) + 1e-6)

    # Phase 1: Targeted swaps of high-impact items
    high_impact_items = np.where(normalized_scores >= 0.7)[0]
    low_impact_items = np.where(normalized_scores < 0.3)[0]

    for hi in high_impact_items:
        if new_solution[hi] == 0 and current_weight + weight_lst[hi] <= capacity:
            for li in low_impact_items:
                if new_solution[li] == 1 and current_weight - weight_lst[li] + weight_lst[hi] <= capacity:
                    new_solution[li], new_solution[hi] = new_solution[hi], new_solution[li]
                    current_weight = current_weight - weight_lst[li] + weight_lst[hi]
                    break

    # Phase 2: Probabilistic perturbations
    for i in range(len(new_solution)):
        if np.random.rand() < 0.1:
            if new_solution[i] == 1:
                if current_weight - weight_lst[i] <= capacity:
                    new_solution[i] = 0
                    current_weight -= weight_lst[i]
            else:
                if current_weight + weight_lst[i] <= capacity:
                    new_solution[i] = 1
                    current_weight += weight_lst[i]

    # Ensure feasibility
